    bridgeResourceLabels: ["WikiHow bridge guide", "Make: Warren truss article", "YouTube build video"],
    bridgeAnatomyTerms: [
      {
        term: "Top Chord",
        definition: "The long top beam of each truss. It usually feels compression when the bridge is loaded, meaning it gets squeezed.",
      },
      {
        term: "Bottom Chord",
        definition: "The long bottom beam. It typically handles tension, meaning it gets pulled apart when weight presses down.",
      },
      {
        term: "Web Members",
        definition: "The diagonal and vertical sticks inside the truss. They transfer force between the two chords and keep the triangles from collapsing.",
      },
      {
        term: "Deck",
        definition: "The road surface of the bridge. When you add weight, the deck is what receives it first and spreads it into the trusses.",
      },
      {
        term: "Top Lateral Bracing",
        definition: "The sticks across the top that tie both side trusses together. Without them, the sides can lean inward like floppy picture frames.",
      },
    ],
    bridgeBuildSteps: [
      {
        title: "Mark 16 sticks and cut splice pieces",
        detail: "Mark about 16 popsicle sticks at the quarter points. Then cut 4 of them in half so you have short pieces ready for overlapping the long rail joints.",
      },
      {
        title: "Glue two long rails",
        detail: "Line up the quarter marks and splice whole sticks together into 2 long rails, each about 4 stick lengths (roughly 18 inches). These become the top and bottom chords.",
      },
      {
        title: "Build the first side with 4 triangle panels",
        detail: "Lay one rail flat and glue 4 upright triangles onto it in a row. Keep spacing even because this first side is the template for the whole bridge.",
      },
      {
        title: "Add 3 staggered triangles between them",
        detail: "Fill the gaps with 3 more triangles so the side becomes a staggered crisscross truss instead of just a row of separate shapes.",
      },
      {
        title: "Cap the truss and sandwich it",
        detail: "Flip the side, glue on the top rail to connect the triangle tips, then add another layer of sticks over the faces to make the truss stiffer.",
      },
      {
        title: "Repeat to build the second side",
        detail: "Build a matching second truss the same way. Both sides must be identical or the deck will twist during the load test.",
      },
      {
        title: "Let sides harden, then connect them squarely",
        detail: "Wait about 15 minutes. Stand both trusses upright, glue cross pieces between them keeping the sides perpendicular, and leave small overhangs where the video shows.",
      },
      {
        title: "Add top, bottom, and diagonal braces",
        detail: "Glue the remaining cross pieces so both top and bottom connectors tie into the side trusses. Add diagonal supports inside and along the outer faces.",
      },
      {
        title: "Reinforce, cure again, and load test carefully",
        detail: "Reinforce any weak joints, let the full bridge harden again, then test slowly between two supports. Add weight a little at a time.",
      },
    ],
    or: "OR",
