    post27Excerpt: "Your phone does not know who you are. It matches face patterns. Learn how cameras, sensors, and machine learning work together behind face unlock.",
    post28Title: "Why Does Autocorrect Make Weird Mistakes?",
    post28Excerpt: "Autocorrect predicts words based on patterns, not understanding. Learn why it struggles with names, slang, and creative spelling, and how it is related to AI.",
    post29Title: "What Happens When You Ask AI a Question?",
    post29Excerpt: "Between your question and the answer, AI is running through a process of prompts, training, and prediction. Here is how it works, step by step.",
    post30Title: "Should Kids Trust Everything AI Says?",
    post30Excerpt: "AI can be helpful and creative, but it can also be wrong. Learn how to think like a detective, what topics need extra care, and how to protect your privacy.",
    post31Title: "How Do Video Games Use AI?",
    post31Excerpt: "Enemies that chase you, characters that react, and games that get harder as you improve are all driven by behavior rules. Learn how game AI actually works.",
    post32Title: "Is a Robot the Same Thing as AI?",
    post32Excerpt: "A robot is a physical machine. AI is software that makes decisions. They can work together but they are different. Learn what sensors, motors, and AI each do.",
    post33Title: "How Do Robots Know Where They Are?",
    post33Excerpt: "Robots use cameras, wheel sensors, GPS, and lidar to estimate their location. Learn how robots sense, map, and navigate the world, and why they still get lost.",
    post34Title: "Why Robots Are Bad at Easy Human Tasks",
    post34Excerpt: "Folding laundry and opening doors are simple for humans but hard for robots. Learn why everyday tasks challenge robots and what that tells us about human ability.",
    post35Title: "What Makes a Robot a Robot?",
    post35Excerpt: "A robot senses the world, makes decisions, and takes action. Learn the three parts every robot has and why robots do not need to look like people.",
    post36Title: "How Mars Rovers Drive Without a Driver",
    post36Excerpt: "Mars is too far away for remote control. Learn how rovers use cameras, wheels, instructions from Earth, and careful software to explore another planet.",
    post37Title: "Why Robot Hands Are So Hard to Make",
    post37Excerpt: "Gripping different objects takes movement, strength, and touch all at once. Learn why robot hands are one of the most interesting challenges in robotics.",
    post38Title: "How Factory Robots Build Cars",
    post38Excerpt: "Factory robots weld, paint, and move car parts with precision. Learn how robotic arms are programmed, kept safe, and used alongside human workers on the assembly line.",
    post39Title: "Why Is the Sky Blue but Sunsets Are Orange?",
    post39Excerpt: "The sky looks blue during the day, but at sunset it can turn orange, pink, or red. The reason has to do with sunlight, air, and the way tiny particles scatter colors.",
    post40Title: "Why Do Your Ears Pop on an Airplane?",
    post40Excerpt: "Your ears pop on airplanes because the air pressure around you changes quickly. Your body has a small pressure-balancing system that helps fix it.",
    post41Title: "Why Does Metal Feel Colder Than Wood?",
    post41Excerpt: "Metal and wood can be the same temperature, but metal often feels colder because it pulls heat from your hand much faster.",
    post42Title: "Why Do Bikes Stay Balanced When Moving?",
    post42Excerpt: "Bikes stay balanced because of motion, steering, wheel design, and constant tiny corrections from the rider.",
    post43Title: "Why Do We Slip on Ice?",
    post43Excerpt: "Ice is slippery because it has low friction, and a thin layer of water can make it even harder for your shoes to grip.",
    post44Title: "How Do Noise-Canceling Headphones Work?",
    post44Excerpt: "Noise-canceling headphones use microphones, speakers, and sound waves to reduce unwanted noise before it reaches your ears.",
    post45Title: "Why Do Some Things Float and Others Sink?",
    post45Excerpt: "Floating and sinking depend on density, shape, weight, and how much water an object pushes out of the way.",
    post46Title: "Why Do Magnets Stick to Some Metals but Not Others?",
    post46Excerpt: "Magnets stick to some metals because of how tiny magnetic regions inside the material line up. Not all metals have the right structure for this.",
    readTime3: "3 min",
    readTime4: "4 min",
    readTime5: "5 min",
    readTime6: "6 min",
    readTime7: "7 min",
    codingCategory: "Coding",
    scienceCategory: "Science",
    lightCategory: "Light & Optics",
    post47Title: "How Does a Camera Work Without a Lens?",
    post47Excerpt: "A cardboard box with one pinhole makes a real, upside-down, full-color picture. Here is why, and why a smaller hole is sharper but darker.",
    post48Title: "How Do Fiber Optic Cables Work?",
    post48Excerpt: "Light travels in straight lines, so how does it follow a cable across the ocean floor? It does not bend. It gets trapped.",
    post49Title: "How Do Scientists Know What Stars Are Made Of?",
    post49Excerpt: "Nobody has been to a star. We know their ingredients anyway, because every element leaves its own pattern of lines in light.",
    post50Title: "Why Do Things Glow Under a Blacklight?",
    post50Excerpt: "Tonic water and highlighters are not reflecting the lamp. They are absorbing light you cannot see and making new light of their own.",
    post51Title: "Is Light a Wave or a Particle?",
    post51Excerpt: "It interferes like a wave and arrives like a particle. Two centuries of argument, and what you can and cannot see at home.",
