    sortName: "Sorting Race",
    sortTagline: "Watch four sorting algorithms race the same numbers in real time.",
    sortEyebrow: "Algorithms",
    sortTitle: "Which sort wins the race?",
    sortDesc: "Same shuffled bars, four different ways to sort them. Speed up or slow down to see how each algorithm thinks.",
