    sortSelection: "Selection sort",
    sortQuick: "Quicksort",
    sortMerge: "Merge sort",
    sortHeap: "Heap sort",
    sortBubbleHint: "Like students lining up by height, it compares two neighboring bars and swaps them if they are in the wrong order. After many passes, the biggest bars bubble to the end.",
    sortInsertionHint: "Like sorting cards in your hand, it takes one bar at a time and slides it into the correct place among the bars that are already sorted.",
    sortSelectionHint: "Like picking the shortest person for the front of the line, it finds the smallest remaining bar, moves it to the front, and repeats.",
    sortQuickHint: "It chooses one pivot bar, then sorts the other bars into smaller and larger groups around it. Then it sorts those smaller groups the same way.",
    sortMergeHint: "Like splitting a big deck of cards into tiny piles, it sorts the small piles first, then carefully merges them back together in order.",
    sortHeapHint: "Like making a pile where the biggest toy is always on top, it moves the biggest bar to the end, rebuilds the pile, and repeats.",
    sortFactEyebrow: "Algorithm fact",
    sortFactBefore: "Bubble and selection do roughly n² steps. Quicksort, merge sort, and heap sort are usually closer to n·log n, which is why they often pull ahead as the array grows.",
    sortFactAfter: "All six reach the same answer, but the number of steps it took shows why algorithm choice matters at scale.",

