    journeyTitle: "The Three Maker Mindset Workshops",
    journeyDesc: "The series is built as three separate workshops: Building, Coding, and AI. They are usually held about one week apart. Each session gives students a new way to think like a maker: understand a problem, create something real, and reflect on how technology should be used.",
    approachEyebrow: "Our Approach",
    approachTitle: "Why the Series Works",
    approachP1: "The Maker Mindset Series turns big STEM topics into simple, active learning experiences. Students do not need prior experience; they need curiosity, encouragement, and room to try.",
    approachP2: "Our goal is to help students see themselves as people who can build, debug, question, and create. That confidence matters long after the final workshop ends.",
