    week2: "Workshop Two",
    week3: "Workshop Three",
    buildingTitle: "Building",
    buildingDesc: "Students start with engineering and design. They learn how mechanical, electrical, civil, and chemical engineers solve real problems, then connect those ideas to hands on building challenges that make engineering feel concrete and approachable.",
    codingWorkshopTitle: "Coding",
    codingWorkshopDesc: "The second workshop introduces Python in a beginner friendly way. With guided practice, each student builds a simple game by the end of the session, giving them a real first coding win instead of just a lecture about programming.",
    aiWorkshopTitle: "Artificial Intelligence",
    aiWorkshopDesc: "The final workshop helps students understand AI through examples they recognize, like video recommendations and Spotify song suggestions. They learn how AI systems process information, make predictions, and affect everyday choices.",
    responsibleAi: "Responsible AI",
    responsibleAiNote: "Just as importantly, students are taught how to use AI responsibly without becoming overly dependent on it. They learn that AI is a powerful tool for learning and creating, but it should be used thoughtfully because overuse can reduce critical thinking and independent learning.",
    handsOnShortDesc: "Incorporating activities that reinforce concepts through real interaction.",
    realWorldRelevance: "Real World Relevance",
