    cliftonDesc: "This program was hosted at the Clifton Public Library in Clifton, New Jersey, where I taught a group of 3rd to 5th grade students through interactive STEM activities. We also held an extra session for a hands on Coke and Mentos demonstration, used to explain the science behind the eruption and introduce the concept of physical vs. chemical changes, learning to figure out why it is actually a physical reaction rather than a chemical change.",
    allwoodLibrary: "Allwood Branch Library",
    allwoodDesc: "This program was held at the Allwood Branch Library, where I taught a group of grade school students through several fun, hands on STEM activities. The session encouraged students to explore core scientific concepts through engaging demonstrations and guided experimentation.",
    chathamsLibrary: "Library of the Chathams",
    chathamsDesc: "This program was held at the Library of the Chathams, where we led grade school students through hands-on STEM activities designed to make engineering and science feel approachable, fun, and interactive. Students explored STEM concepts through guided building challenges, demonstrations, and collaborative problem solving.",
    roselandLibrary: "Roseland Free Public Library",
    roselandDesc: "This program was hosted at the Roseland Free Public Library, where students participated in engaging, hands-on STEM activities focused on creativity, experimentation, and teamwork. The session encouraged students to explore science and engineering ideas through interactive projects and guided demonstrations.",
    wayneLibrary: "Wayne Public Library",
    wayneDesc: "This program was hosted at the Wayne Public Library, where students participated in engaging, hands-on STEM activities focused on creativity, experimentation, and teamwork. The session encouraged students to explore science and engineering ideas through interactive projects and guided demonstrations.",
    veronaLibrary: "Verona Public Library",
    veronaDesc: "This program was held at the Verona Public Library, where students worked through hands-on building challenges that turned engineering ideas into something they could design, test, and improve together. Working in small groups kept every student involved, from the first sketch to the finished build.",
    littleFallsLibrary: "Little Falls Public Library",
    littleFallsDesc: "This program was hosted at the Little Falls Public Library, where students followed along on laptops through a beginner-friendly introduction to coding. Step-by-step demonstrations and guided practice gave each student the chance to write and run their own programs during the session.",
