    post7Excerpt: "三角形是工程中最坚固的形状，出现在每座桥、每座塔和每个桁架中，也是冰棒棍桥的关键。",
    post8Title: "工程师在东西坏掉时是怎么想的",
    post8Excerpt: "一个断裂的结构会告诉你薄弱点在哪里。这是将一次失败的构建变成更强设计的思维过程。",
    post9Title: "用纸板设计一辆火星探测车",
    post9Excerpt: "一个动手工程挑战：用纸板和胶带设计并建造火星探测车，面对与真实太空工程师相同的设计限制。",
    post10Title: "AI 回答你时实际上在做什么？",
    post10Excerpt: "AI 回答问题时，并不是在搜索网络或查询存储的数据。这是实际发生的事情，以及它为什么听起来正确却可能出错。",
    post11Title: "如何在 20 分钟内像发明家一样思考",
    post11Excerpt: "一个现在就能试的设计挑战：找一个小问题，画出解决方案，制作一个简单原型，然后测试它。",
    post12Title: "为什么你的第一个设计通常不是最好的",
    post12Excerpt: "一次桥梁测试可以让学生看清第一个设计缺少什么，以及下一步该改进什么。",
    post13Title: "背包里的工程学",
    post13Excerpt: "背带、拉链、面料和口袋都是工程决策。这里探讨你每天背去学校的东西背后的设计思维。",
    post15Title: "什么让 STEM 工作坊变得有趣？",
    post15Excerpt: "看看 Avanza STEM 如何设计活动，让学生在搭建、测试和探索中学习，而不是安静地坐着听人讲解。",
    post16Title: "校车里隐藏的工程学",
    post16Excerpt: "校车里装满了工程决策。了解颜色、座椅、镜子和紧急出口如何共同合作，安全地运送孩子们。",
    post17Title: "为什么飞机机翼是弯曲的？",
    post17Excerpt: "飞机机翼是弯曲的，因为形状控制气流。了解翼型设计如何产生升力，以及为什么是机翼，而不只是发动机，让飞机飞起来。",
    post18Title: "电梯如何知道去哪里？",
    post18Excerpt: "电梯使用按钮、传感器、电机、配重和控制逻辑来安全地运送人员，这一切都隐藏在那个简单的按钮按压背后。",
    post19Title: "为什么高楼会随风摇动？",
    post19Excerpt: "高楼故意设计成会摇动的。了解为什么一点弹性让摩天大楼更安全，以及隐藏在内部的巨大阻尼器如何减少晃动。",
    post20Title: "足球背后的工程学",
    post20Excerpt: "形状、气压、面板设计和材料都影响足球如何滚动、弹跳和在空中弯曲飞行。",
    post21Title: "为什么井盖是圆形的？",
    post21Excerpt: "井盖是圆形的，因为这种形状安全、坚固、易于移动，而且不可能掉进孔里。一个设计解决多个问题。",
    post22Title: "过山车如何不脱轨？",
    post22Excerpt: "重力、动量、多侧轮系统和精心设计的环形轨道共同作用，让过山车保持在轨道上，即使倒着走。",
    post23Title: "为什么有些椅子会断，有些不会？",
    post23Excerpt: "椅子的强度取决于重量分布、材料选择、接头质量和形状。了解为什么摇晃的椅子是个警告信号。",
    post24Title: "水瓶里隐藏的工程学",
    post24Excerpt: "一次性塑料瓶是轻量化工程的成果，但 PET 材料、瓶盖摩擦、微塑料和废弃物也带来取舍。",
    post25Title: "AI 真的会思考吗？",
    post25Excerpt: "AI 可以回答问题、写故事，但它真的在思考吗？了解 AI 如何使用模式识别，以及为什么这与人类大脑的工作方式不同。",
    post26Title: "为什么 AI 有时会出错？",
    post26Excerpt: "AI 根据模式做出自信的预测，但这些预测可能是错的。了解什么是幻觉，以及如何核查 AI 告诉你的信息。",
    post27Title: "你的手机是怎么识别你的脸的？",
    post27Excerpt: "你的手机不是真的认识你。它匹配的是面部特征模式。了解摄像头、传感器和机器学习如何在人脸解锁中协同工作。",
    post28Title: "自动更正为什么会犯奇怪的错误？",
    post28Excerpt: "自动更正根据模式而不是理解来预测单词。了解它为什么在名字和俚语上出错，以及它与 AI 的关系。",
    post29Title: "你向 AI 提问时发生了什么？",
    post29Excerpt: "在你的问题和答案之间，AI 经历了提示、训练和预测的过程。下面我们一步一步来了解它是如何工作的。",
    post30Title: "孩子应该相信 AI 说的一切吗？",
    post30Excerpt: "AI 可以很有帮助，也很有创意，但它也会出错。学习如何像侦探一样思考，哪些话题需要格外小心，以及如何保护你的隐私。",
    post31Title: "电子游戏是怎么使用 AI 的？",
    post31Excerpt: "追着你跑的敌人、会反应的角色和越来越难的游戏，都是由行为规则驱动的。了解游戏 AI 是如何真正工作的。",
    post32Title: "机器人和 AI 是同一回事吗？",
    post32Excerpt: "机器人是一台实体机器，AI 是做决策的软件。它们可以一起工作，但它们是不同的东西。了解传感器、电机和 AI 各自的作用。",
    post33Title: "机器人怎么知道自己在哪里？",
    post33Excerpt: "机器人用摄像头、轮式传感器、GPS 和激光雷达来估算位置。了解机器人如何感知、绘图和导航，以及为什么有时还是会迷路。",
    post34Title: "机器人为什么做不好人类轻松完成的事？",
    post34Excerpt: "叠衣服、开门对人类来说很简单，但对机器人却很难。了解日常任务为什么会挑战机器人，以及这说明了什么。",
    post35Title: "什么使机器人成为机器人？",
    post35Excerpt: "机器人感知世界、做出决策并采取行动。了解每个机器人都有的三个部分，以及为什么机器人不必长得像人。",
    post36Title: "火星探测器怎么在没有驾驶员的情况下行驶？",
    post36Excerpt: "火星太远，无法遥控。了解探测器如何利用摄像头、轮子和来自地球的指令来探索另一个星球。",
    post37Title: "为什么机器人手这么难制造？",
    post37Excerpt: "抓取不同的物体需要同时具备运动、力量和触觉。了解为什么机器人手是机器人技术中最有趣的挑战之一。",
    post38Title: "工厂机器人是如何造汽车的？",
    post38Excerpt: "工厂机器人以精准和一致性焊接、喷漆和搬运零部件。了解机械臂如何被编程，以及它们如何与工人协同工作。",
    post39Title: "天空为什么是蓝色的，日落却是橙色的？",
    post39Excerpt: "白天天空看起来是蓝色的，但日落时可能变成橙色、粉红色或红色。原因与阳光、空气以及微小粒子散射颜色的方式有关。",
    post40Title: "为什么飞机上耳朵会嗡嗡作响？",
    post40Excerpt: "飞机上耳朵会嗡嗡作响，是因为周围的气压迅速变化。你的身体有一个小型的气压平衡系统来帮助调节。",
    post41Title: "为什么金属摸起来比木头冷？",
    post41Excerpt: "金属和木头可能是同样的温度，但金属通常感觉更冷，因为它能更快地从你的手上带走热量。",
    post42Title: "自行车为什么在运动时能保持平衡？",
    post42Excerpt: "自行车能保持平衡，是因为运动、转向、车轮设计以及骑手不断进行的微小修正共同作用。",
    post43Title: "我们为什么会在冰上滑倒？",
    post43Excerpt: "冰很滑，因为它的摩擦力很低，而且一层薄薄的水膜会让鞋子更难抓地。",
    post44Title: "降噪耳机是怎么工作的？",
    post44Excerpt: "降噪耳机利用麦克风、扬声器和声波，在不需要的噪音到达耳朵之前将其减弱。",
    post45Title: "为什么有些东西会浮，有些东西会沉？",
    post45Excerpt: "浮或沉取决于密度、形状、重量以及物体排开多少水。",
    post46Title: "为什么磁铁只吸一些金属，而不是所有金属？",
    post46Excerpt: "磁铁能吸附某些金属，是因为这些材料内部的微小磁性区域会排列对齐。并非所有金属都具备这种结构。",
