    post47Title: "没有镜头的相机是怎么工作的？",
    post47Excerpt: "一个只开了针孔的纸盒，能呈现出真实、倒立、彩色的画面。这是原因所在，以及为什么孔越小越清晰、也越暗。",
    post48Title: "光纤电缆是怎么工作的？",
    post48Excerpt: "光沿直线传播，那它是怎么沿着海底的电缆一路走下去的？它并没有拐弯，而是被困住了。",
    post49Title: "科学家怎么知道恒星是由什么构成的？",
    post49Excerpt: "没有人去过恒星。我们却知道它们的成分，因为每一种元素都会在光里留下自己独有的谱线。",
    post50Title: "为什么有些东西在黑光灯下会发亮？",
    post50Excerpt: "汤力水和荧光笔并不是在反射灯光。它们吸收了你看不见的光，然后自己发出了新的光。",
    post51Title: "光是波还是粒子？",
    post51Excerpt: "它像波一样发生干涉，又像粒子一样抵达。两个世纪的争论，以及在家里你能看见什么、看不见什么。",
