    tommyBio: "Enqi \"Tommy\" Qi 通过在动手工作坊中指导学生、用照片记录活动，并在需要额外帮助时提供支持来参与 Avanza STEM。他稳定的支持让每场活动更有秩序、更温暖，也更适合孩子们学习。",
