    journeyTitle: "As três oficinas da Série Mentes Criadoras",
    journeyDesc: "A série é formada por três oficinas separadas: construção, programação e IA, geralmente realizadas com cerca de uma semana de intervalo. Cada encontro dá aos estudantes um novo jeito de pensar como criadores: entender um problema, criar algo de verdade e refletir sobre como usar a tecnologia.",
    approachEyebrow: "Nosso jeito de fazer",
    approachTitle: "Por que a série funciona",
    approachP1: "A Série Mentes Criadoras transforma grandes temas de STEM em experiências simples, ativas e participativas. Os estudantes não precisam de experiência prévia; precisam de curiosidade, apoio e espaço para tentar.",
    approachP2: "Nosso objetivo é que os estudantes se enxerguem como pessoas capazes de construir, depurar, perguntar e criar. Essa confiança faz diferença muito depois da última oficina.",
