    engagementTitle: "O que torna nossos programas eficazes",
    week1: "Oficina um",
    week2: "Oficina dois",
    week3: "Oficina três",
    buildingTitle: "Construção",
    buildingDesc: "Os estudantes começam pela engenharia e pelo projeto. Eles descobrem como engenheiros mecânicos, elétricos, civis e químicos resolvem problemas reais e ligam essas ideias a desafios práticos de construção.",
    codingWorkshopTitle: "Programação",
    codingWorkshopDesc: "A segunda oficina apresenta o Python de um jeito acolhedor para iniciantes. Com prática guiada, cada estudante cria um jogo simples até o fim do encontro e vive uma primeira experiência real de programação.",
    aiWorkshopTitle: "Inteligência artificial",
    aiWorkshopDesc: "A última oficina ajuda os estudantes a entender a IA com exemplos que eles reconhecem, como as recomendações de vídeos e as músicas do Spotify. Eles aprendem como os sistemas de IA processam informações, fazem previsões e influenciam decisões do dia a dia.",
    responsibleAi: "IA responsável",
    responsibleAiNote: "Igualmente importante: os estudantes aprendem a usar a IA de forma responsável, sem depender demais dela. Eles percebem que a IA é uma ferramenta poderosa para aprender e criar, mas que precisa ser usada com critério.",
    handsOnShortDesc: "Incluir atividades que reforçam os conceitos por meio de interação de verdade.",
    realWorldRelevance: "Ligação com o mundo real",
