    cliftonLibrary: "Biblioteca Pública de Clifton",
    cliftonDesc: "Este programa aconteceu na Biblioteca Pública de Clifton, em Clifton, Nova Jersey, onde ensinei um grupo de estudantes do 3º ao 5º ano com atividades de STEM interativas. Também fizemos um encontro extra, com uma demonstração prática de Coca-Cola e Mentos, para explicar a ciência por trás da erupção e apresentar o conceito de mudanças físicas e químicas.",
    allwoodLibrary: "Biblioteca Allwood Branch",
    allwoodDesc: "Este programa aconteceu na Biblioteca Allwood Branch, onde ensinei um grupo de estudantes do ensino fundamental com várias atividades de STEM divertidas e práticas. O encontro incentivou os estudantes a explorar conceitos científicos fundamentais com demonstrações interessantes e experimentação guiada.",
    chathamsLibrary: "Library of the Chathams",
    chathamsDesc: "Este programa aconteceu na Library of the Chathams, onde conduzimos estudantes do ensino fundamental por atividades práticas de STEM pensadas para deixar a engenharia e a ciência acessíveis, divertidas e interativas. Os estudantes exploraram conceitos de STEM com desafios de construção guiados, demonstrações e resolução de problemas em grupo.",
    roselandLibrary: "Roseland Free Public Library",
    roselandDesc: "Este programa aconteceu na Roseland Free Public Library, onde os estudantes participaram de atividades práticas de STEM com foco em criatividade, experimentação e trabalho em equipe. O encontro incentivou os estudantes a explorar ideias de ciência e engenharia com projetos interativos e demonstrações guiadas.",
    wayneLibrary: "Wayne Public Library",
    wayneDesc: "Este programa aconteceu na Wayne Public Library, onde os estudantes participaram de atividades práticas de STEM com foco em criatividade, experimentação e trabalho em equipe. O encontro incentivou os estudantes a explorar ideias de ciência e engenharia com projetos interativos e demonstrações guiadas.",
    veronaLibrary: "Verona Public Library",
    veronaDesc: "Este programa aconteceu na Verona Public Library, onde os estudantes encararam desafios práticos de construção que transformaram ideias de engenharia em algo que eles podiam projetar, testar e melhorar juntos. Trabalhar em grupos pequenos manteve cada estudante participando, do primeiro rascunho até a construção pronta.",
    littleFallsLibrary: "Little Falls Public Library",
    littleFallsDesc: "Este programa aconteceu na Little Falls Public Library, onde os estudantes acompanharam a aula em notebooks, com uma introdução à programação para iniciantes. As demonstrações passo a passo e a prática guiada deram a cada estudante a chance de escrever e executar os próprios programas durante o encontro.",
